<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class CrmController extends Controller {
 private function table(string$type):string{abort_unless(in_array($type,['customers','suppliers']),404);return$type;}
 private function entity(Request$r,string$type,int$id):object{return DB::table($this->table($type))->where(['id'=>$id,'company_id'=>$r->user()->company_id])->firstOrFail();}
 public function detail(Request$r,string$type,int$id){$e=$this->entity($r,$type,$id);$c=$r->user()->company_id;$e->addresses=DB::table('crm_addresses')->where(['company_id'=>$c,'entity_type'=>$type,'entity_id'=>$id])->get();$e->contacts=DB::table('crm_contacts')->where(['company_id'=>$c,'entity_type'=>$type,'entity_id'=>$id])->get();$e->notes=DB::table('crm_notes as n')->leftJoin('users as u','u.id','=','n.user_id')->where(['n.company_id'=>$c,'n.entity_type'=>$type,'n.entity_id'=>$id])->select('n.*','u.name as user_name')->latest('n.id')->get();$e->documents=DB::table('documents')->where(['company_id'=>$c,'entity_type'=>$type,'entity_id'=>$id])->latest()->get();if($type==='customers'){$e->history=DB::table('sales')->where(['company_id'=>$c,'customer_id'=>$id])->latest()->get();$e->account=['sales'=>(float)DB::table('sales')->where(['company_id'=>$c,'customer_id'=>$id])->where('status','!=','cancelled')->sum('total'),'returns'=>(float)DB::table('sale_returns as r')->join('sales as s','s.id','=','r.sale_id')->where(['r.company_id'=>$c,'s.customer_id'=>$id])->sum('r.total')];}else{$e->history=DB::table('purchases')->where(['company_id'=>$c,'supplier_id'=>$id])->latest()->get();$e->products=DB::table('product_suppliers as ps')->join('products as pr','pr.id','=','ps.product_id')->leftJoin('purchase_details as d','d.product_id','=','pr.id')->leftJoin('purchases as p',fn($j)=>$j->on('p.id','=','d.purchase_id')->where('p.supplier_id','=',$id)->where('p.status','=','confirmed'))->where(['ps.company_id'=>$c,'ps.supplier_id'=>$id])->groupBy('ps.id','pr.id','pr.name','pr.sku')->selectRaw('ps.*,pr.id as product_id,pr.name,pr.sku,COALESCE(SUM(CASE WHEN p.id IS NOT NULL THEN d.quantity ELSE 0 END),0) quantity')->get();$returned=DB::table('purchase_return_details as rd')->join('purchase_returns as r','r.id','=','rd.purchase_return_id')->join('purchases as p','p.id','=','r.purchase_id')->where(['p.company_id'=>$c,'p.supplier_id'=>$id,'p.status'=>'confirmed'])->groupBy('rd.product_id')->selectRaw('rd.product_id,SUM(rd.quantity) quantity')->pluck('quantity','product_id');foreach($e->products as $row)$row->quantity=(float)$row->quantity-(float)($returned[$row->product_id]??0);$total=(float)DB::table('purchases')->where(['company_id'=>$c,'supplier_id'=>$id,'status'=>'confirmed'])->sum('total');$returns=(float)DB::table('purchase_returns as r')->join('purchases as p','p.id','=','r.purchase_id')->where(['p.company_id'=>$c,'p.supplier_id'=>$id,'p.status'=>'confirmed'])->sum('r.total');$paid=(float)DB::table('purchase_payments as pp')->join('purchases as p','p.id','=','pp.purchase_id')->where(['p.company_id'=>$c,'p.supplier_id'=>$id,'p.status'=>'confirmed'])->sum('pp.amount');$e->account=['purchases'=>$total,'returns'=>$returns,'paid'=>$paid,'balance'=>round($total-$returns-$paid,2)];}return response()->json(['success'=>true,'data'=>$e]);}
 public function update(Request$r,string$type,int$id){$this->entity($r,$type,$id);$base=['name'=>'required','document_type'=>'nullable|in:DNI,RUC,CE,PASSPORT','document_number'=>\App\Support\DocumentRules::number($r->input('document_type')),'phone'=>'nullable','email'=>'nullable|email','address'=>'nullable','status'=>'required'];if($type==='suppliers')$base['contact']='nullable';$d=$r->validate($base);DB::table($type)->where(['id'=>$id,'company_id'=>$r->user()->company_id])->update($d+['updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Ficha actualizada']);}
 public function addAddress(Request$r,string$type,int$id){$this->entity($r,$type,$id);$d=$r->validate(['label'=>'required','address'=>'required','district'=>'nullable','city'=>'nullable','reference'=>'nullable','is_default'=>'boolean']);if(!empty($d['is_default']))DB::table('crm_addresses')->where(['company_id'=>$r->user()->company_id,'entity_type'=>$type,'entity_id'=>$id])->update(['is_default'=>false]);$aid=DB::table('crm_addresses')->insertGetId($d+['company_id'=>$r->user()->company_id,'entity_type'=>$type,'entity_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Dirección guardada','data'=>['id'=>$aid]],201);}
 public function addContact(Request$r,string$type,int$id){$this->entity($r,$type,$id);$d=$r->validate(['name'=>'required','position'=>'nullable','phone'=>'nullable','email'=>'nullable|email','is_primary'=>'boolean']);if(!empty($d['is_primary']))DB::table('crm_contacts')->where(['company_id'=>$r->user()->company_id,'entity_type'=>$type,'entity_id'=>$id])->update(['is_primary'=>false]);$cid=DB::table('crm_contacts')->insertGetId($d+['company_id'=>$r->user()->company_id,'entity_type'=>$type,'entity_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Contacto guardado','data'=>['id'=>$cid]],201);}
 public function addNote(Request$r,string$type,int$id){$this->entity($r,$type,$id);$note=$r->validate(['note'=>'required|string'])['note'];$nid=DB::table('crm_notes')->insertGetId(['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'entity_type'=>$type,'entity_id'=>$id,'note'=>$note,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Observación registrada','data'=>['id'=>$nid]],201);}
 public function deleteRelated(Request$r,string$type,int$id,string$relation,int$related){$this->entity($r,$type,$id);$table=match($relation){'addresses'=>'crm_addresses','contacts'=>'crm_contacts','notes'=>'crm_notes',default=>abort(404)};DB::table($table)->where(['id'=>$related,'company_id'=>$r->user()->company_id,'entity_type'=>$type,'entity_id'=>$id])->delete();return response()->json(['success'=>true,'message'=>'Registro eliminado']);}
}
